42	struct src_ip_info_t {
43	  IpAddr start;               ///< Minimum value in range.
44	  IpAddr end;                 ///< Maximum value in range.
45	  bool   invert;              ///< Should we "invert" the meaning of this IP range ("not in range")
46	  bool   match_all_addresses; ///< This rule should match all IP addresses.
47	
48	  void
49	  reset()
50	  {
51	    start.invalidate();
52	    end.invalidate();
53	    invert              = false;
54	    match_all_addresses = false;
55	  }
56	
57	  /// @return @c true if @a ip is inside @a this range.
58	  bool
59	  contains(IpEndpoint const &ip) const
60	  {
61	    if (match_all_addresses) {
62	      return true;
63	    }
64	    IpAddr addr{ip};
65	    return addr.cmp(start) >= 0 && addr.cmp(end) <= 0;
66	  }
67	};
