69	struct src_ip_category_info_t {
70	  std::string category;       ///< The IP category for this remap rule.
71	  bool        invert = false; ///< Should we "invert" the meaning of these IP categories ("not in categories")
72	
73	  void
74	  reset()
75	  {
76	    category.clear();
77	    invert = false;
78	  }
79	
80	  /// @return @c true if @a ip is inside @a this categories.
81	  bool
82	  contains(IpEndpoint const &ip) const
83	  {
84	    return ask_ip_allow_about_category(category, swoc::IPAddr{ip});
85	  }
86	
87	private:
88	  bool ask_ip_allow_about_category(std::string const &category, swoc::IPAddr const &addr) const;
89	};
