54	/**
55	  Returns the length of the URL.
56	
57	  Will replace the terminator with a '/' if this is a full URL and
58	  there are no '/' in it after the host.  This ensures that class
59	  URL parses the URL correctly.
60	
61	*/
62	static int
63	UrlWhack(char *toWhack, int *origLength)
64	{
65	  int   length = strlen(toWhack);
66	  char *tmp;
67	  *origLength = length;
68	
69	  // Check to see if this a full URL
70	  tmp = strstr(toWhack, "://");
71	  if (tmp != nullptr) {
72	    if (strchr(tmp + 3, '/') == nullptr) {
73	      toWhack[length] = '/';
74	      length++;
75	    }
76	  }
77	  return length;
78	}
