158	static bool
159	is_inkeylist(const char *key, ...)
160	{
161	  va_list ap;
162	
163	  if (unlikely(key == nullptr || key[0] == '\0')) {
164	    return false;
165	  }
166	
167	  va_start(ap, key);
168	
169	  const char *str = va_arg(ap, const char *);
170	  while (str) {
171	    if (!strcasecmp(key, str)) {
172	      va_end(ap);
173	      return true;
174	    }
175	
176	    str = va_arg(ap, const char *);
177	  }
178	
179	  va_end(ap);
180	  return false;
181	}
